import csv
import io
import re
from typing import List, Dict, Union


def parse_csv(raw_csv: str) -> Union[str, Dict[str, List]]:
    try:
        csv.field_size_limit(1000000000)
    except (OverflowError, ValueError):
        pass

    stream = io.StringIO(raw_csv, newline="")
    try:
        parsed_rows = list(csv.reader(stream, delimiter=",", quotechar='"', doublequote=True))
    except csv.Error:
        stream.seek(0)
        parsed_rows = list(
            csv.reader(
                stream,
                delimiter=",",
                quotechar='"',
                doublequote=True,
                strict=False,
            )
        )

    if not parsed_rows:
        return {"columns": [], "rows": []}

    def header_key(value: str) -> str:
        value = value.lstrip("\ufeff").strip().lower()
        return re.sub(r"[^a-z0-9]+", "", value)

    known_headers = {
        "date",
        "time",
        "qty",
        "quantity",
        "productid",
        "price",
        "producttype",
        "productdescription",
        "description",
        "url",
        "comments",
        "comment",
    }

    header_index = -1
    best_score = -1
    for index, row in enumerate(parsed_rows):
        keys = [header_key(value) for value in row]
        score = sum(1 for key in keys if key in known_headers)
        if "date" in keys:
            score += 2
        if "productid" in keys:
            score += 2
        if "url" in keys:
            score += 1
        if score > best_score:
            best_score = score
            header_index = index
        if score >= 7:
            break

    if best_score < 3:
        header_index = next(
            (i for i, row in enumerate(parsed_rows) if any(value != "" for value in row)),
            0,
        )

    columns = list(parsed_rows[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    expected_width = len(columns)
    data_rows = parsed_rows[header_index + 1:]

    semantic_keys = [header_key(value) for value in columns]
    semantic_layout = (
        expected_width == 9
        and len(semantic_keys) >= 8
        and semantic_keys[0] == "date"
        and "productid" in semantic_keys
        and "url" in semantic_keys
    )

    connector_words = {
        "a", "an", "and", "at", "by", "for", "from", "in", "of", "on",
        "or", "the", "to", "with",
    }

    def is_title_phrase(text: str) -> bool:
        words = re.findall(r"[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*", text)
        if not words or len(words) > 5:
            return False

        for word in words:
            plain = word.strip("'’-")
            if not plain:
                continue
            if plain.lower() in connector_words:
                continue
            if plain[0].isdigit():
                continue
            if not plain[0].isupper() and not plain.isupper():
                return False
        return True

    def find_description_split(parts: List[str]) -> int:
        if len(parts) <= 1:
            return len(parts)

        for index in range(1, len(parts)):
            fragment = parts[index].strip()
            words = re.findall(r"[A-Za-z0-9]+(?:['’-][A-Za-z0-9]+)*", fragment)
            if len(words) >= 4 or len(fragment) >= 30 or not is_title_phrase(fragment):
                return index

        return 1

    def repair_semantic_row(row: List[str]) -> List[str]:
        values = [value.replace('""', '"') for value in row]

        if len(values) < 6:
            return values + [""] * (9 - len(values))

        url_index = -1
        for index in range(5, len(values)):
            if re.match(r"^\s*(?:https?|ftp)://", values[index], re.IGNORECASE):
                url_index = index
                break
            if re.match(r"^\s*www\.", values[index], re.IGNORECASE):
                url_index = index
                break

        if url_index < 0:
            if len(values) <= 9:
                return values + [""] * (9 - len(values))
            url_index = len(values) - 2

        middle = values[5:url_index]
        if len(middle) >= 2:
            split_at = find_description_split(middle)
            product_type = ",".join(middle[:split_at])
            product_description = ",".join(middle[split_at:])
        elif len(middle) == 1:
            product_type = middle[0]
            product_description = ""
        else:
            product_type = ""
            product_description = ""

        url = values[url_index] if url_index < len(values) else ""
        comments = ",".join(values[url_index + 1:]) if url_index + 1 < len(values) else ""

        return values[:5] + [
            product_type,
            product_description,
            url,
            comments,
        ]

    def repair_generic_row(row: List[str]) -> List[str]:
        values = list(row)
        if len(values) == expected_width:
            return values
        if len(values) < expected_width:
            return values + [""] * (expected_width - len(values))
        if expected_width <= 1:
            return [",".join(values)]
        return values[:expected_width - 1] + [",".join(values[expected_width - 1:])]

    output_rows = []
    for row in data_rows:
        if semantic_layout:
            repaired = repair_semantic_row(row)
        else:
            repaired = repair_generic_row(row)

        if len(repaired) < expected_width:
            repaired += [""] * (expected_width - len(repaired))
        elif len(repaired) > expected_width:
            repaired = repaired[:expected_width - 1] + [
                ",".join(repaired[expected_width - 1:])
            ]

        output_rows.append([str(value) for value in repaired])

    return {"columns": [str(value) for value in columns], "rows": output_rows}
